SELECT 
FROM submission_review_log
WHERE submission_id = #{submissionId}
  AND submission_version = #{submissionVersion}
LIMIT 1

SELECT COALESCE(MAX(round_no), 0) + 1
FROM submission_review_log
WHERE submission_id = #{submissionId}

SELECT COUNT(*)
FROM submission_review_log
WHERE submission_id = #{submissionId}
